import { spawn } from 'node:child_process';
import { mkdtemp, realpath, readFile, writeFile, rm } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { connect } from 'node:net';
import path from 'node:path';
const BASE='/tmp/codex-tool-runs/svton/m2-r2-atomic-review-20261002';
const MODULE='file:///Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/file-lock.js';
const BIND='file:///Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/lock-bindtest.js';
const ROOT=await realpath(await mkdtemp('/tmp/ship-publish-review-'));
const file=path.join(ROOT,'state.json');
const claim=path.join('/var/tmp/shipkit-lock-ports',createHash('sha256').update(file).digest('hex').slice(0,20)+'.json');
const children=[];
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function worker(name,pauseFirstBind) {
  const code=`
import { mock } from 'node:test';
import { readFile, writeFile } from 'node:fs/promises';
const file=${JSON.stringify(file)},claim=${JSON.stringify(claim)};
let resume,release;
process.on('message',m=>{if(m==='resume')resume?.();if(m==='release')release?.();if(m==='exit')process.exit(0);});
if(${pauseFirstBind}) {
  const real=await import(${JSON.stringify(BIND)});
  let first=true;
  mock.module(${JSON.stringify(BIND)},{namedExports:{bindTest:async(port)=>{
    if(first){first=false;const gate=new Promise(r=>resume=r);process.send({event:'paused',port});await gate;}
    return real.bindTest(port); // ALL syscall results are real; only scheduling is paused
  }}});
}
const {withFileLock}=await import(${JSON.stringify(MODULE)});
process.send({event:'started'});
try {
  await withFileLock(file,async()=>{
    const gate=new Promise(r=>release=r);
    const old=Number(await readFile(file,'utf8'));
    const published=JSON.parse(await readFile(claim,'utf8'));
    process.send({event:'entered',old,port:published.port});
    await gate;await writeFile(file,String(old+1));
  },{timeoutMs:1800});
  process.send({event:'finished'});
}catch(e){process.send({event:'error',message:e.message});}
`;
  const child=spawn(process.execPath,['--experimental-test-module-mocks','--input-type=module','-e',code],{stdio:['ignore','ignore','pipe','ipc']});
  children.push(child);
  const messages=[];
  child.on('message',m=>messages.push(m));
  child.stderr.on('data',d=>messages.push({event:'stderr',text:String(d)}));
  return {name,child,messages,async wait(event,ms=3000){
    const until=Date.now()+ms;
    while(Date.now()<until){const m=messages.find(m=>m.event===event);if(m)return m;if(messages.some(m=>m.event==='error'))return null;await sleep(5);}
    return null;
  }};
}
async function banner(port){
  return new Promise(resolve=>{
    const socket=connect({host:'127.0.0.1',port});
    const finish=value=>{socket.destroy();resolve(value);};
    socket.setTimeout(300,()=>finish('timeout'));
    socket.once('data',d=>finish(String(d).trim()));socket.once('error',e=>finish(e.code));
  });
}
try {
  await writeFile(file,'0');
  const delayed=worker('B-delayed',true);
  const pause=await delayed.wait('paused');
  if(!pause)throw Error('B did not reach real first bind scheduling point');
  const holder=worker('A-holder',false);
  const first=await holder.wait('entered');
  if(!first)throw Error('A did not acquire: '+JSON.stringify(holder.messages));
  const claimBefore=JSON.parse(await readFile(claim,'utf8'));
  delayed.child.send('resume');
  const second=await delayed.wait('entered',500);
  const claimAfter=JSON.parse(await readFile(claim,'utf8'));
  const firstBanner=await banner(first.port);
  const secondBanner=second ? await banner(second.port) : null;
  holder.child.send('release');
  if(second)delayed.child.send('release');
  await holder.wait('finished');
  if(!second){await delayed.wait('entered');delayed.child.send('release');}
  await delayed.wait('finished');
  const result={schedule:'B read no existing claim and paused BEFORE its first REAL bindTest; A published, bound and kept its section; B resumed the real bind, skipped occupied A port, published a different claim and entered before A released.',
    simultaneousSections:second?2:1,first,second,pause,claimBefore,claimAfter,
    liveBannersWhileBothHeld:[firstBanner,secondBanner],finalValue:Number(await readFile(file,'utf8')),expected:2,
    holderMessages:holder.messages,delayedMessages:delayed.messages,
    method:'Only a scheduling barrier is injected using node:test mock.module for bindTest. The imported original bindTest is called unchanged after resume. All fs operations, listen/connect outcomes, child processes and counter values are real.'};
  await writeFile(`${BASE}/publish-race-result.json`,JSON.stringify(result,null,2));
  console.log(JSON.stringify({simultaneousSections:result.simultaneousSections,first,second,claimBefore,claimAfter,liveBanners:result.liveBannersWhileBothHeld,finalValue:result.finalValue}));
  holder.child.send('exit');delayed.child.send('exit');
} finally {
  for(const c of children)if(c.exitCode===null)c.kill('SIGTERM');
  await sleep(50);
  await rm(ROOT,{recursive:true,force:true});
  await rm(claim,{force:true}); // ONLY this reproduction's fresh UUID-derived claim
}

